#!/usr/bin/env node

import { createHash } from "node:crypto";
import { mkdir, mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { buildDmSdkCallSymbolIndex } from "../packages/compiler/src/dmsdk-call-symbol-index.mjs";
import {
  dmSdkUniversalReadyCorpusArtifacts,
  materializeDmSdkUniversalReadyCorpus,
} from "../packages/compiler/src/dmsdk-universal-ready-corpus.mjs";
import { materializeDmSdkUsages } from "../packages/compiler/src/dmsdk-universal-materializer-core.mjs";
import { generateDmSdkBrowserArena } from "../packages/compiler/src/sdk/support-sdk.mjs";
import {
  assertDmSdkUniversalStaticFrameCapacity,
  emitDmSdkUniversalStaticFrame,
} from "../packages/compiler/src/dmsdk-universal-static-frame.mjs";

const repositoryRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const defaultProjectionPath = "packages/bindings/generated/defold-dmsdk-projection-ir.json";
const defaultSdkIrPath = "packages/bindings/generated/defold-sdk-ir.json";
const defaultSpecializedReportPaths = Object.freeze({
  arenaCString: "packages/bindings/generated/defold-dmsdk-arena-span-blockers.json",
  borrowedHandle: "packages/bindings/generated/defold-dmsdk-borrowed-handle-bindings.json",
  scratchScalarOut: "packages/bindings/generated/defold-dmsdk-scratch-scalar-out-bindings.json",
  cstringValue: "packages/bindings/generated/defold-dmsdk-cstring-value-bindings.json",
  hashState: "packages/bindings/generated/defold-dmsdk-hash-state-bindings.json",
});
const banner = "Generated by scripts/generate-dmsdk-universal-bindings.mjs. Do not edit.";

const artifacts = Object.freeze([
  "packages/bindings/generated/defold-dmsdk-universal-bindings.json",
  "defold/defold_hermes/include/defold_hermes/generated_dmsdk_universal.h",
  "defold/defold_hermes/include/defold_hermes/generated_dmsdk_universal_jsi.hpp",
  "defold/defold_hermes/src/generated_dmsdk_universal.cpp",
  "defold/defold_hermes/src/generated_dmsdk_universal_jsi.cpp",
  "defold/defold_hermes/lib/web/generated_dmsdk_universal.js",
  "packages/sdk/src/generated/dmsdk/universal.ts",
  "packages/sdk/src/generated/dmsdk/browser-arena.ts",
  "packages/static-hermes/src/generated/dmsdk-universal.ts",
  "packages/compiler/src/generated/dmsdk-universal-recipes.mjs",
  "tests/fixtures/generated_dmsdk_universal_test_provider.cpp",
  "tests/fixtures/generated_dmsdk_universal_test_ids.h",
  "defold/defold_hermes/include/defold_hermes/generated_dmsdk_universal_static_frame.h",
  "defold/defold_hermes/src/generated_dmsdk_universal_static_frame.cpp",
  dmSdkUniversalReadyCorpusArtifacts.plan,
  dmSdkUniversalReadyCorpusArtifacts.productionSource,
  dmSdkUniversalReadyCorpusArtifacts.verificationSource,
]);

const valueKind = Object.freeze({
  void: "void", scalar: "scalar", enum: "enum", cstring: "cstring", array: "memory",
  pointer: "pointer", reference: "pointer", record: "record", "template-record": "record",
  handle: "handle", callback: "callback", named: "named", template: "template",
  "type-parameter": "type-parameter", variadic: "variadic", opaque: "opaque", unknown: "unknown",
});

function sha256(value) { return createHash("sha256").update(value).digest("hex"); }

function parseArguments(argv) {
  const options = { check: false, outRoot: repositoryRoot, projection: defaultProjectionPath, sdkIr: defaultSdkIrPath };
  for (let index = 0; index < argv.length; index += 1) {
    const argument = argv[index];
    if (argument === "--check") options.check = true;
    else if (argument === "--out-root") options.outRoot = path.resolve(argv[++index]);
    else if (argument === "--projection") options.projection = argv[++index];
    else if (argument === "--sdk-ir") options.sdkIr = argv[++index];
    else throw new Error(`Unknown argument: ${argument}`);
  }
  return options;
}

function walk(node, visit) {
  visit(node);
  for (const key of ["to", "target", "representation", "element", "result"]) if (node?.[key]) walk(node[key], visit);
  for (const child of node?.parameters ?? []) walk(child, visit);
  for (const child of node?.arguments ?? []) walk(child, visit);
}

function nodeKinds(node) {
  const kinds = new Set();
  walk(node, (value) => kinds.add(value.kind));
  return [...kinds].sort();
}

function carriesRecordByValue(node, behindIndirection = false) {
  if (!node || typeof node !== "object") return false;
  if (["record", "template-record"].includes(node.kind)) return !behindIndirection;
  const nextBehindIndirection = behindIndirection ||
    ["pointer", "reference", "handle", "callback", "opaque"].includes(node.kind);
  for (const key of ["to", "target", "representation", "element", "result"]) {
    if (carriesRecordByValue(node[key], nextBehindIndirection)) return true;
  }
  for (const key of ["parameters", "arguments"]) {
    for (const child of node[key] ?? []) {
      if (carriesRecordByValue(child, nextBehindIndirection)) return true;
    }
  }
  return false;
}

function includePath(header) {
  const marker = "/dmsdk/";
  const index = header.lastIndexOf(marker);
  return index < 0 ? header : `dmsdk/${header.slice(index + marker.length)}`;
}

function ownerOf(row) {
  if (row.provenance.declarationKind === "function") return null;
  const pieces = row.symbol.split("::");
  if (pieces.length < 2) return null;
  return pieces.slice(0, -1).join("::");
}

function leafOf(symbol) { return symbol.split("::").at(-1); }

function invocationKind(kind) {
  return ({
    function: "direct-function",
    method: "member-function",
    constructor: "placement-constructor",
    destructor: "explicit-destructor",
    "function-template": "function-template-specialization",
  })[kind];
}

function templateParameters(row) {
  const values = new Set();
  const visit = (node) => {
    if (node.kind === "type-parameter" && node.name) values.add(node.name);
    if (node.kind === "template" && node.name) values.add(node.name);
  };
  walk(row.signature.result, visit);
  for (const parameter of row.signature.parameters) walk(parameter.type, visit);
  for (const match of row.provenance.nativeSignature.matchAll(/\b(?:T|U|V|KEY|VALUE)\b/g)) values.add(match[0]);
  return [...values].sort();
}

function enumFact(shape, row, declarations) {
  if (shape.kind !== "enum") return null;
  let matches = declarations.filter((declaration) =>
    declaration.kind === "enum" && declaration.name === shape.name);
  if (matches.length !== 1) {
    const leaf = shape.name.split("::").at(-1);
    matches = declarations.filter((declaration) =>
      declaration.kind === "enum" && declaration.header === row.provenance.header &&
      declaration.name.split("::").at(-1) === leaf);
  }
  if (matches.length !== 1) {
    throw new Error(`${row.id} enum ${shape.name} resolves to ${matches.length} SDK declarations`);
  }
  const declaration = matches[0];
  const members = (declaration.members ?? []).map(({ name, value }) => ({ name, value }));
  if (!members.length || members.some(({ name, value }) =>
    typeof name !== "string" || !name || !Number.isSafeInteger(value))) {
    throw new Error(`${row.id} enum ${shape.name} has no complete safe-integer domain`);
  }
  return {
    declarationId: declaration.id,
    nativeName: declaration.name,
    domain: shape.domain ?? "declared-values",
    members,
  };
}

function requirementFor(node) {
  const kinds = nodeKinds(node);
  const requirements = [];
  if (kinds.includes("unknown")) requirements.push("native-type-substitution");
  if (carriesRecordByValue(node)) requirements.push("record-layout");
  if (kinds.includes("template") || kinds.includes("type-parameter")) requirements.push("template-arguments");
  if (kinds.includes("variadic")) requirements.push("typed-nonvariadic-facade");
  if (kinds.includes("callback")) requirements.push("callback-trampoline");
  if (kinds.some((kind) => ["pointer", "reference", "cstring", "handle", "opaque"].includes(kind))) requirements.push("pointer-lifetime");
  return requirements;
}

function buildRecipe(row, declaration, numericId, specialized, context) {
  const kind = row.provenance.declarationKind;
  const receiver = ownerOf(row);
  const hasReceiver = ["method", "constructor", "destructor"].includes(kind);
  const parameters = row.signature.parameters.map((parameter) => {
    const enumeration = enumFact(parameter.type, row, context.declarations);
    return {
      position: parameter.position,
      name: parameter.name,
      nativeType: parameter.nativeType,
      direction: parameter.direction,
      cellKind: valueKind[parameter.type.kind],
      shape: parameter.type,
      requirements: requirementFor(parameter.type),
      ...(enumeration ? { enumeration } : {}),
    };
  });
  const resultRequirements = requirementFor(row.signature.result);
  const resultEnumeration = enumFact(row.signature.result, row, context.declarations);
  const requirements = new Set([...row.semanticTokensNeeded, ...resultRequirements, ...parameters.flatMap((item) => item.requirements)]);
  if (hasReceiver) requirements.add("receiver-native-type");
  const templates = templateParameters(row);
  if (kind === "function-template" && templates.length === 0) requirements.add("explicit-template-arguments");
  const specializedEntry = specialized.get(row.id);
  const specializedFamily = specializedEntry?.family;
  return {
    numericId,
    declarationId: row.id,
    projectionId: row.projectionId,
    symbol: row.symbol,
    header: row.provenance.header,
    include: includePath(row.provenance.header),
    line: row.provenance.line,
    declarationKind: kind,
    invocation: {
      kind: invocationKind(kind),
      nativeSymbol: row.symbol,
      sourceDefined: row.provenance.sourceDefined === true,
      member: ["method", "constructor", "destructor"].includes(kind) ? leafOf(row.symbol) : null,
      receiver: hasReceiver ? {
        required: true,
        mode: kind === "constructor" ? "construction-storage" : "object",
        owner: receiver,
        nativeType: receiver && !context.templatedReceiverOwners.has(receiver) ? receiver : null,
        source: receiver && !context.templatedReceiverOwners.has(receiver)
          ? "source-derived-nontemplate-owner"
          : "usage-substitution-required",
      } : null,
      templateArguments: { names: templates, source: "usage-required-when-unresolved" },
      monomorphization: kind === "function-template" ? {
        required: true,
        signatureSource: parameters.length || row.signature.result.kind !== "void" ? "projection-or-usage-override" : "usage-required",
        usageInputs: ["templateArguments", "parameters", "resultCppType", "resultShape", "nativeSymbol"],
      } : null,
    },
    abi: {
      argumentOffset: hasReceiver ? 1 : 0,
      argumentCount: parameters.length + (hasReceiver ? 1 : 0),
      resultKind: valueKind[row.signature.result.kind],
      resultNativeType: declaration.returns ?? "void",
      resultShape: row.signature.result,
      ...(resultEnumeration ? { resultEnumeration } : {}),
      parameters,
      frame: "DehermDmSdkUniversalFrame/v1",
    },
    targets: {
      cAbi: { path: "universal-provider-dispatch", usageMaterializer: "@deherm/compiler/dmsdk-universal-materializer" },
      dynamicHermes: { path: "generated-jsi-registration-metadata", module: "DmSdkUniversal" },
      staticHermes: { path: "generated-extern-c-direct-memory" },
      browserWasm: { path: "generated-emscripten-direct-memory", embind: false },
      typescript: { path: "generated-stable-id-api" },
    },
    preferredLowering: specializedFamily
      ? {
        ...(row.loweringState === "generated-adapter"
          ? row.lowering
          : { state: "generated-adapter", family: specializedFamily, wrapper: null }),
        adapter: specializedEntry.adapter,
      }
      : { state: "universal-fallback", family: "universal-recipe" },
    fallback: {
      state: "materializable",
      requirements: [...requirements].sort(),
      silentOmissionAllowed: false,
    },
  };
}

function renderHeader(maxArguments, catalogHash) {
  return `// ${banner}\n#ifndef DEFOLD_HERMES_GENERATED_DMSDK_UNIVERSAL_H\n#define DEFOLD_HERMES_GENERATED_DMSDK_UNIVERSAL_H\n\n#include <stdint.h>\n\n#define DEHERM_DMSDK_UNIVERSAL_MAX_ARGUMENTS ${maxArguments}\n\ntypedef enum DehermDmSdkUniversalStatus {\n  DEHERM_DMSDK_UNIVERSAL_OK = 0,\n  DEHERM_DMSDK_UNIVERSAL_UNKNOWN_ID = 1,\n  DEHERM_DMSDK_UNIVERSAL_WRONG_ARITY = 2,\n  DEHERM_DMSDK_UNIVERSAL_NO_PROVIDER = 3,\n  DEHERM_DMSDK_UNIVERSAL_INVALID_STORAGE = 4,\n  DEHERM_DMSDK_UNIVERSAL_PROVIDER_ERROR = 5,\n  DEHERM_DMSDK_UNIVERSAL_TYPE_MISMATCH = 6\n} DehermDmSdkUniversalStatus;\n\ntypedef enum DehermDmSdkUniversalValueTag {\n  DEHERM_DMSDK_UNIVERSAL_VOID = 0,\n  DEHERM_DMSDK_UNIVERSAL_BOOL = 1,\n  DEHERM_DMSDK_UNIVERSAL_I64 = 2,\n  DEHERM_DMSDK_UNIVERSAL_U64 = 3,\n  DEHERM_DMSDK_UNIVERSAL_F64 = 4,\n  DEHERM_DMSDK_UNIVERSAL_ADDRESS = 5,\n  DEHERM_DMSDK_UNIVERSAL_MEMORY = 6,\n  DEHERM_DMSDK_UNIVERSAL_CALLBACK = 7,\n  DEHERM_DMSDK_UNIVERSAL_NATIVE_VALUE = 8\n} DehermDmSdkUniversalValueTag;\n\ntypedef struct DehermDmSdkUniversalValue {\n  uint64_t payload;\n  uint64_t auxiliary;\n  uint32_t tag;\n  uint32_t type_id;\n} DehermDmSdkUniversalValue;\n\ntypedef struct DehermDmSdkUniversalDescriptor {\n  uint32_t id;\n  uint16_t argument_count;\n  uint8_t declaration_kind;\n  uint8_t flags;\n} DehermDmSdkUniversalDescriptor;\n\ntypedef DehermDmSdkUniversalStatus (*DehermDmSdkUniversalProvider)(\n    void* context, const DehermDmSdkUniversalDescriptor* descriptor,\n    const DehermDmSdkUniversalValue* arguments, uint32_t argument_count,\n    DehermDmSdkUniversalValue* result);\n\n#ifdef __cplusplus\nextern \"C\" {\n#endif\nuint32_t deherm_dmsdk_universal_count(void);\nconst char* deherm_dmsdk_universal_catalog_sha256(void);\nconst DehermDmSdkUniversalDescriptor* deherm_dmsdk_universal_descriptors(void);\nconst DehermDmSdkUniversalDescriptor* deherm_dmsdk_universal_find(uint32_t id);\nvoid deherm_dmsdk_universal_install_provider(DehermDmSdkUniversalProvider provider, void* context);\nDehermDmSdkUniversalStatus deherm_dmsdk_universal_dispatch(\n    uint32_t id, const DehermDmSdkUniversalValue* arguments, uint32_t argument_count,\n    DehermDmSdkUniversalValue* result);\n#ifdef __cplusplus\n}\n#endif\n\n#endif\n`;
}

const kindCode = Object.freeze({ function: 1, method: 2, constructor: 3, destructor: 4, "function-template": 5 });

function renderCpp(recipes, catalogHash) {
  const rows = recipes.map((recipe) => `  {UINT32_C(${recipe.numericId}), UINT16_C(${recipe.abi.argumentCount}), UINT8_C(${kindCode[recipe.declarationKind]}), UINT8_C(${recipe.preferredLowering.state === "generated-adapter" ? 1 : 0})}`).join(",\n");
  return `// ${banner}\n#include <defold_hermes/generated_dmsdk_universal.h>\n\n#include <stddef.h>\n\nnamespace {\nconst DehermDmSdkUniversalDescriptor kDescriptors[] = {\n${rows}\n};\nDehermDmSdkUniversalProvider g_provider = nullptr;\nvoid* g_context = nullptr;\n}\n\nextern \"C\" {\nuint32_t deherm_dmsdk_universal_count(void) { return UINT32_C(${recipes.length}); }\nconst char* deherm_dmsdk_universal_catalog_sha256(void) { return ${JSON.stringify(catalogHash)}; }\nconst DehermDmSdkUniversalDescriptor* deherm_dmsdk_universal_descriptors(void) { return kDescriptors; }\nconst DehermDmSdkUniversalDescriptor* deherm_dmsdk_universal_find(uint32_t id) {\n  return id < deherm_dmsdk_universal_count() && kDescriptors[id].id == id ? &kDescriptors[id] : nullptr;\n}\nvoid deherm_dmsdk_universal_install_provider(DehermDmSdkUniversalProvider provider, void* context) {\n  g_provider = provider; g_context = context;\n}\nDehermDmSdkUniversalStatus deherm_dmsdk_universal_dispatch(\n    uint32_t id, const DehermDmSdkUniversalValue* arguments, uint32_t argument_count,\n    DehermDmSdkUniversalValue* result) {\n  const DehermDmSdkUniversalDescriptor* descriptor = deherm_dmsdk_universal_find(id);\n  if (!descriptor) return DEHERM_DMSDK_UNIVERSAL_UNKNOWN_ID;\n  if (descriptor->declaration_kind != UINT8_C(5) && argument_count != descriptor->argument_count) return DEHERM_DMSDK_UNIVERSAL_WRONG_ARITY;\n  if (argument_count && !arguments) return DEHERM_DMSDK_UNIVERSAL_INVALID_STORAGE;\n  if (!result) return DEHERM_DMSDK_UNIVERSAL_INVALID_STORAGE;\n  if (!g_provider) return DEHERM_DMSDK_UNIVERSAL_NO_PROVIDER;\n  return g_provider(g_context, descriptor, arguments, argument_count, result);\n}\n}\n`;
}

function renderJsiHeader(recipeCount) {
  return `// ${banner}\n#pragma once\n#include <stdint.h>\n#if !defined(DM_PLATFORM_HTML5)\n#include <jsi/jsi.h>\n#endif\nnamespace defold_hermes {\nstruct DmSdkUniversalJsiRegistrationMetadata {\n  const char* module_name;\n  const char* method_name;\n  uint32_t recipe_count;\n  uint32_t value_bytes;\n};\ninline constexpr DmSdkUniversalJsiRegistrationMetadata kDmSdkUniversalJsiRegistration = {\n  "DmSdkUniversal", "call", UINT32_C(${recipeCount}), UINT32_C(24)\n};\n#if !defined(DM_PLATFORM_HTML5)\nvoid installDmSdkUniversalModule(facebook::jsi::Runtime& runtime, facebook::jsi::Object& modules);\n#endif\n}\n`;
}

function renderJsiSource(catalogHash) {
  return `// ${banner}
#include <defold_hermes/generated_dmsdk_universal_jsi.hpp>
#if !defined(DM_PLATFORM_HTML5)
#include <defold_hermes/generated_dmsdk_universal.h>
#include <cmath>
#include <cstring>
#include <limits>
#include <string>
#include <vector>
namespace defold_hermes { namespace jsi=facebook::jsi; namespace {
bool integer(const jsi::Value& value){return value.isNumber()&&std::isfinite(value.asNumber())&&std::trunc(value.asNumber())==value.asNumber();}
uint32_t u32(jsi::Runtime& runtime,const jsi::Value& value,const char* label){if(!integer(value)||value.asNumber()<0||value.asNumber()>4294967295.0)throw jsi::JSError(runtime,std::string(label)+" must be u32");return static_cast<uint32_t>(value.asNumber());}
uint64_t u64(jsi::Runtime& runtime,const jsi::Value& value,const char* label,bool nonzero){if(!value.isBigInt())throw jsi::JSError(runtime,std::string(label)+" must be bigint");auto bigint=value.getBigInt(runtime);if(!bigint.isUint64(runtime))throw jsi::JSError(runtime,std::string(label)+" is outside u64");const uint64_t raw=bigint.asUint64(runtime);if(nonzero&&raw==0)throw jsi::JSError(runtime,std::string(label)+" must be nonzero");if(sizeof(uintptr_t)<sizeof(uint64_t)&&raw>UINTPTR_MAX)throw jsi::JSError(runtime,std::string(label)+" exceeds target pointer width");return raw;}
DehermDmSdkUniversalValue encode(jsi::Runtime& runtime,const jsi::Value& value,std::vector<std::string>& strings){DehermDmSdkUniversalValue cell{};if(value.isUndefined()||value.isNull()){cell.tag=DEHERM_DMSDK_UNIVERSAL_VOID;return cell;}if(value.isBool()){cell.tag=DEHERM_DMSDK_UNIVERSAL_BOOL;cell.payload=value.getBool()?1:0;return cell;}if(value.isNumber()){const double number=value.asNumber();if(!std::isfinite(number))throw jsi::JSError(runtime,"dmSDK universal number must be finite");cell.tag=DEHERM_DMSDK_UNIVERSAL_F64;std::memcpy(&cell.payload,&number,sizeof(number));return cell;}if(value.isBigInt()){auto bigint=value.getBigInt(runtime);if(bigint.isInt64(runtime)&&bigint.asInt64(runtime)<0){cell.tag=DEHERM_DMSDK_UNIVERSAL_I64;cell.payload=static_cast<uint64_t>(bigint.asInt64(runtime));return cell;}if(!bigint.isUint64(runtime))throw jsi::JSError(runtime,"dmSDK universal bigint is outside i64/u64");cell.tag=DEHERM_DMSDK_UNIVERSAL_U64;cell.payload=bigint.asUint64(runtime);return cell;}if(value.isString()){strings.push_back(value.getString(runtime).utf8(runtime));cell.tag=DEHERM_DMSDK_UNIVERSAL_ADDRESS;cell.payload=reinterpret_cast<uintptr_t>(strings.back().c_str());cell.auxiliary=strings.back().size();return cell;}if(!value.isObject())throw jsi::JSError(runtime,"dmSDK universal value has unsupported type");auto object=value.asObject(runtime);auto kindValue=object.getProperty(runtime,"kind");if(!kindValue.isString())throw jsi::JSError(runtime,"dmSDK universal object needs string kind");const std::string kind=kindValue.getString(runtime).utf8(runtime);if(kind=="i64"){auto raw=object.getProperty(runtime,"value");if(!raw.isBigInt()||!raw.getBigInt(runtime).isInt64(runtime))throw jsi::JSError(runtime,"i64.value is outside i64");cell.tag=DEHERM_DMSDK_UNIVERSAL_I64;cell.payload=static_cast<uint64_t>(raw.getBigInt(runtime).asInt64(runtime));}else if(kind=="u64"){auto raw=object.getProperty(runtime,"value");if(!raw.isBigInt()||!raw.getBigInt(runtime).isUint64(runtime))throw jsi::JSError(runtime,"u64.value is outside u64");cell.tag=DEHERM_DMSDK_UNIVERSAL_U64;cell.payload=raw.getBigInt(runtime).asUint64(runtime);}else if(kind=="address"){cell.tag=DEHERM_DMSDK_UNIVERSAL_ADDRESS;cell.payload=u64(runtime,object.getProperty(runtime,"value"),"address.value",true);}else if(kind=="memory"){cell.tag=DEHERM_DMSDK_UNIVERSAL_MEMORY;cell.payload=u64(runtime,object.getProperty(runtime,"address"),"memory.address",false);cell.auxiliary=u32(runtime,object.getProperty(runtime,"byteLength"),"memory.byteLength");if(cell.payload==0&&cell.auxiliary!=0)throw jsi::JSError(runtime,"non-empty memory needs nonzero address");}else if(kind=="native-value"){cell.tag=DEHERM_DMSDK_UNIVERSAL_NATIVE_VALUE;cell.payload=u64(runtime,object.getProperty(runtime,"address"),"native-value.address",true);cell.type_id=u32(runtime,object.getProperty(runtime,"typeId"),"native-value.typeId");}else throw jsi::JSError(runtime,"unknown dmSDK universal object kind");auto typeId=object.getProperty(runtime,"typeId");if(!typeId.isUndefined())cell.type_id=u32(runtime,typeId,"typeId");return cell;}
jsi::Value decode(jsi::Runtime& runtime,const DehermDmSdkUniversalValue& cell){switch(cell.tag){case DEHERM_DMSDK_UNIVERSAL_VOID:return jsi::Value::undefined();case DEHERM_DMSDK_UNIVERSAL_BOOL:if(cell.payload>1)throw jsi::JSError(runtime,"invalid boolean result");return jsi::Value(cell.payload!=0);case DEHERM_DMSDK_UNIVERSAL_I64:return jsi::Value(runtime,jsi::BigInt::fromInt64(runtime,static_cast<int64_t>(cell.payload)));case DEHERM_DMSDK_UNIVERSAL_U64:return jsi::Value(runtime,jsi::BigInt::fromUint64(runtime,cell.payload));case DEHERM_DMSDK_UNIVERSAL_F64:{double value;std::memcpy(&value,&cell.payload,sizeof(value));return jsi::Value(value);}case DEHERM_DMSDK_UNIVERSAL_ADDRESS:case DEHERM_DMSDK_UNIVERSAL_MEMORY:case DEHERM_DMSDK_UNIVERSAL_NATIVE_VALUE:{jsi::Object object(runtime);const char* kind=cell.tag==DEHERM_DMSDK_UNIVERSAL_ADDRESS?"address":cell.tag==DEHERM_DMSDK_UNIVERSAL_MEMORY?"memory":"native-value";object.setProperty(runtime,"kind",jsi::String::createFromAscii(runtime,kind));object.setProperty(runtime,cell.tag==DEHERM_DMSDK_UNIVERSAL_ADDRESS?"value":"address",jsi::BigInt::fromUint64(runtime,cell.payload));if(cell.tag==DEHERM_DMSDK_UNIVERSAL_MEMORY)object.setProperty(runtime,"byteLength",static_cast<double>(cell.auxiliary));if(cell.tag==DEHERM_DMSDK_UNIVERSAL_NATIVE_VALUE||cell.type_id)object.setProperty(runtime,"typeId",static_cast<double>(cell.type_id));return object;}default:throw jsi::JSError(runtime,"unknown dmSDK universal result tag");}}
const char* status(DehermDmSdkUniversalStatus value){switch(value){case DEHERM_DMSDK_UNIVERSAL_UNKNOWN_ID:return "unknown id";case DEHERM_DMSDK_UNIVERSAL_WRONG_ARITY:return "wrong arity";case DEHERM_DMSDK_UNIVERSAL_NO_PROVIDER:return "no usage-materialized provider";case DEHERM_DMSDK_UNIVERSAL_INVALID_STORAGE:return "invalid storage";case DEHERM_DMSDK_UNIVERSAL_TYPE_MISMATCH:return "type mismatch";default:return "provider error";}}
}
void installDmSdkUniversalModule(jsi::Runtime& runtime,jsi::Object& modules){if(std::strcmp(deherm_dmsdk_universal_catalog_sha256(),${JSON.stringify(catalogHash)})!=0)throw jsi::JSError(runtime,"dmSDK universal catalog identity mismatch");jsi::Object module(runtime);module.setProperty(runtime,"catalogSha256",jsi::String::createFromAscii(runtime,${JSON.stringify(catalogHash)}));auto call=jsi::Function::createFromHostFunction(runtime,jsi::PropNameID::forAscii(runtime,"call"),2,[](jsi::Runtime& runtime,const jsi::Value&,const jsi::Value* args,size_t count)->jsi::Value{if(count!=2||!integer(args[0])||args[0].asNumber()<0||args[0].asNumber()>4294967295.0||!args[1].isObject()||!args[1].asObject(runtime).isArray(runtime))throw jsi::JSError(runtime,"DmSdkUniversal.call expects (u32 id, values[])");const uint32_t id=static_cast<uint32_t>(args[0].asNumber());const auto* descriptor=deherm_dmsdk_universal_find(id);if(!descriptor||descriptor->id!=id)throw jsi::JSError(runtime,"unknown dmSDK universal id");auto array=args[1].asObject(runtime).asArray(runtime);const size_t length=array.size(runtime);if(length>DEHERM_DMSDK_UNIVERSAL_MAX_ARGUMENTS||(descriptor->declaration_kind!=UINT8_C(5)&&length!=descriptor->argument_count))throw jsi::JSError(runtime,"wrong dmSDK universal arity");DehermDmSdkUniversalValue values[DEHERM_DMSDK_UNIVERSAL_MAX_ARGUMENTS]{};std::vector<std::string> strings;strings.reserve(length);for(size_t index=0;index<length;++index)values[index]=encode(runtime,array.getValueAtIndex(runtime,index),strings);DehermDmSdkUniversalValue result{};const auto outcome=deherm_dmsdk_universal_dispatch(id,values,static_cast<uint32_t>(length),&result);if(outcome!=DEHERM_DMSDK_UNIVERSAL_OK)throw jsi::JSError(runtime,std::string("dmSDK universal dispatch: ")+status(outcome));return decode(runtime,result);});module.setProperty(runtime,"call",std::move(call));modules.setProperty(runtime,"DmSdkUniversal",std::move(module));}
}
#endif
`;
}

function renderWeb(recipes, maxArguments, catalogHash) {
  const metadata = recipes.map(({ numericId, declarationId, symbol, declarationKind, abi, projectionId }) => ({ id: numericId, declarationId, symbol, declarationKind, argumentCount: abi.argumentCount, resultKind: abi.resultKind, recipeId: projectionId }));
  return `// ${banner}\nvar LibraryDefoldHermesDmSdkUniversal={\n  $DEFOLD_HERMES_DMSDK_UNIVERSAL__deps:["deherm_dmsdk_universal_dispatch","deherm_dmsdk_universal_catalog_sha256"],\n  $DEFOLD_HERMES_DMSDK_UNIVERSAL:{\n    catalogSha256:${JSON.stringify(catalogHash)},\n    abi:Object.freeze({valueBytes:24,maxArguments:${maxArguments},dispatch:'direct-memory',embind:false}),\n    recipes:Object.freeze(${JSON.stringify(metadata)}),\n    callRaw:function(id,argumentsPointer,argumentCount,resultPointer){return _deherm_dmsdk_universal_dispatch(id,argumentsPointer,argumentCount,resultPointer);}\n  }\n};\nautoAddDeps(LibraryDefoldHermesDmSdkUniversal,'$DEFOLD_HERMES_DMSDK_UNIVERSAL');\naddToLibrary(LibraryDefoldHermesDmSdkUniversal);\n`;
}

function renderTypeScript(recipes, catalogHash) {
  const ids = recipes.map((recipe) => `  ${JSON.stringify(recipe.declarationId)}: ${recipe.numericId},`).join("\n");
  return `// ${banner}\nexport const DMSDK_UNIVERSAL_CATALOG_SHA256=${JSON.stringify(catalogHash)};\nexport type DmSdkUniversalDeclarationId = keyof typeof DmSdkUniversalId;\nexport type DmSdkUniversalValue = undefined | boolean | number | bigint | string | DmSdkUniversalI64 | DmSdkUniversalU64 | DmSdkUniversalAddress | DmSdkUniversalMemory | DmSdkUniversalNativeValue;\nexport interface DmSdkUniversalI64 { readonly kind:"i64"; readonly value:bigint; }\nexport interface DmSdkUniversalU64 { readonly kind:"u64"; readonly value:bigint; }\nexport interface DmSdkUniversalAddress { readonly kind:"address"; readonly value:bigint; readonly typeId?:number; }\nexport interface DmSdkUniversalMemory { readonly kind:"memory"; readonly address:bigint; readonly byteLength:number; readonly typeId?:number; }\nexport interface DmSdkUniversalNativeValue { readonly kind:"native-value"; readonly address:bigint; readonly typeId:number; }\nexport interface DmSdkUniversalBridge { readonly catalogSha256:string; call(id:number,args:readonly DmSdkUniversalValue[]):DmSdkUniversalValue; }\ndeclare global { var __defoldModulesV1:Record<string,object>|undefined; }\nlet bridge:DmSdkUniversalBridge|undefined;\nexport function installDmSdkUniversalBridge(value:DmSdkUniversalBridge):void{bridge=value;}\nfunction requireBridge():DmSdkUniversalBridge{\n  const value=bridge??globalThis.__defoldModulesV1?.DmSdkUniversal as DmSdkUniversalBridge|undefined;\n  if(!value)throw new Error("Defold module is not registered: DmSdkUniversal");\n  if(value.catalogSha256!==DMSDK_UNIVERSAL_CATALOG_SHA256)throw new Error("DmSdkUniversal catalog identity mismatch");\n  return value;\n}\nexport const DmSdkUniversalId={\n${ids}\n} as const;\nexport function callDmSdkUniversal(id:DmSdkUniversalDeclarationId,args:readonly DmSdkUniversalValue[]):DmSdkUniversalValue{\n  return requireBridge().call(DmSdkUniversalId[id],args);\n}\n`;
}

function renderRecipesModule(recipes, sourceHash, catalogHash) {
  return `// ${banner}\nexport const dmSdkUniversalRecipeSourceSha256=${JSON.stringify(sourceHash)};\nexport const dmSdkUniversalCatalogSha256=${JSON.stringify(catalogHash)};\nexport const dmSdkUniversalRecipes=Object.freeze(${JSON.stringify(recipes)});\nexport const dmSdkUniversalRecipeByDeclarationId=new Map(dmSdkUniversalRecipes.map((recipe)=>[recipe.declarationId,recipe]));\n`;
}

async function writeArtifact(root, relative, contents, check) {
  const target = path.join(root, relative);
  const normalized = contents.endsWith("\n") ? contents : `${contents}\n`;
  if (check) {
    if (await readFile(target, "utf8") !== normalized) throw new Error(`${relative} is stale`);
  } else {
    await mkdir(path.dirname(target), { recursive: true });
    await writeFile(target, normalized);
  }
}

export async function buildUniversalDmSdkBindings({
  root = repositoryRoot,
  outRoot = root,
  projectionPath = defaultProjectionPath,
  sdkIrPath = defaultSdkIrPath,
  specializedReportPaths = defaultSpecializedReportPaths,
} = {}) {
  const [projectionContent, irContent, specializedReports] = await Promise.all([
    readFile(path.resolve(root, projectionPath), "utf8"),
    readFile(path.resolve(root, sdkIrPath), "utf8"),
    Promise.all(Object.entries(specializedReportPaths).map(async ([family, relative]) => {
      const content = await readFile(path.resolve(root, relative), "utf8");
      return [family, content, JSON.parse(content)];
    })),
  ]);
  const projection = JSON.parse(projectionContent);
  const ir = JSON.parse(irContent);
  if (projection.defoldRevision !== ir.defoldRevision) throw new Error("dmSDK universal inputs have different Defold revisions");
  const projectionIds = new Set(projection.rows.map((row) => row.id));
  const specialized = new Map(projection.rows
    .filter((row) => row.loweringState === "generated-adapter")
    .map((row) => [row.id, {
      family: row.lowering.family,
      adapter: {
        applicability: "callable",
        kind: "named-wrapper",
        id: null,
        dispatcher: null,
        blockers: [],
      },
    }]));
  for (const [family, , report] of specializedReports) {
    for (const declaration of [
      ...(report.declarations ?? []),
      ...(report.generatedDeclarations ?? []),
    ]) {
      if (!projectionIds.has(declaration.id) ||
          !["generated", "generated-provider-boundary"].includes(declaration.disposition)) continue;
      const callable = declaration.disposition === "generated";
      specialized.set(declaration.id, {
        family,
        adapter: {
          applicability: callable ? "callable" : "provider-required",
          kind: callable ? "family-dispatch" : "provider-boundary",
          id: callable ? declaration.denseId : declaration.bindingId,
          dispatcher: callable && family === "hashState"
            ? "deherm_dmsdk_hash_state_dispatch"
            : callable && family === "cstringValue"
            ? "deherm_dmsdk_cstring_value_dispatch"
            : callable && family === "arenaCString"
              ? "deherm_dmsdk_arena_cstring_dispatch"
              : null,
          blockers: callable ? [] : [...new Set(declaration.engineProviderBlockers ?? [])].sort(),
        },
      });
    }
  }
  const declarations = new Map(ir.declarations.map((declaration) => [declaration.id, declaration]));
  const templatedReceiverOwners = new Set(projection.rows.flatMap((row) => {
    const owner = ownerOf(row);
    return owner && templateParameters(row).length ? [owner] : [];
  }));
  const context = {
    declarations: [...ir.declarations, ...(ir.typeSupportDeclarations ?? [])],
    templatedReceiverOwners,
  };
  let recipes = projection.rows.map((row, numericId) => {
    const declaration = declarations.get(row.id);
    if (!declaration) throw new Error(`Projection row is absent from SDK IR: ${row.id}`);
    return buildRecipe(row, declaration, numericId, specialized, context);
  });
  const expectedRuntimeDeclarations = ir.runtimeUnimplementedCount ?? projection.rows.length;
  if (recipes.length !== expectedRuntimeDeclarations) throw new Error(`Expected ${expectedRuntimeDeclarations} recipes, got ${recipes.length}`);
  if (new Set(recipes.map(({ declarationId }) => declarationId)).size !== recipes.length) throw new Error("Duplicate universal declaration recipe");
  // A provider-only generated lane is an additional exact boundary, not a
  // reason to hide a universal call that already materializes from the same
  // source-derived recipe. Resolve the candidate catalog once, then make the
  // working universal route the preferred lowering wherever it is complete.
  const candidateCatalogHash = sha256(JSON.stringify(recipes));
  const candidateCatalog = {
    schemaVersion: 1,
    defoldRevision: projection.defoldRevision,
    sourceHashes: { catalog: candidateCatalogHash },
    recipes,
  };
  const candidateIndex = buildDmSdkCallSymbolIndex(ir, candidateCatalog);
  recipes = recipes.map((recipe) => {
    if (recipe.preferredLowering?.adapter?.applicability !== "provider-required" ||
        candidateIndex.declarations[recipe.declarationId]?.materialization?.state !== "universal-ready") {
      return recipe;
    }
    return {
      ...recipe,
      preferredLowering: { state: "universal-fallback", family: "universal-recipe" },
    };
  });
  const maxArguments = Math.max(...recipes.map(({ abi }) => abi.argumentCount));
  assertDmSdkUniversalStaticFrameCapacity({ abi: { maxArguments } });
  const staticFrame = emitDmSdkUniversalStaticFrame();
  const specializedSourceHashes = Object.fromEntries(specializedReports.map(([family, content]) => [family, sha256(content)]));
  const sourceHash = sha256(projectionContent + irContent + specializedReports.map(([family, content]) => `${family}\0${content}`).join(""));
  const catalogHash = sha256(JSON.stringify(recipes));
  const report = {
    schemaVersion: 1,
    defoldRevision: projection.defoldRevision,
    sourceHashes: { projection: sha256(projectionContent), sdkIr: sha256(irContent), specialized: specializedSourceHashes, aggregate: sourceHash, catalog: catalogHash },
    coverage: {
      declarations: recipes.length,
      recipes: recipes.length,
      cAbiDispatchable: recipes.length,
      dynamicHermesMetadata: recipes.length,
      staticHermesDeclarations: recipes.length,
      browserDirectMemoryMetadata: recipes.length,
      typescriptStableIds: recipes.length,
      silentlyOmitted: 0,
      preferredSpecialized: recipes.filter(({ preferredLowering }) => preferredLowering.state === "generated-adapter").length,
      usageMaterializedFallback: recipes.filter(({ preferredLowering }) => preferredLowering.state === "universal-fallback").length,
    },
    abi: { schema: "DehermDmSdkUniversalFrame/v1", valueBytes: 24, maxArguments, allocationPolicy: "caller-owned-fixed-frame" },
    artifacts,
    recipes,
  };
  const callIndex = buildDmSdkCallSymbolIndex(ir, report);
  const readyCorpus = materializeDmSdkUniversalReadyCorpus(callIndex, report);
  report.coverage.universalReadyExactVectors = readyCorpus.report.verification.vectorCount;
  const outputs = new Map([
    [artifacts[0], `${JSON.stringify(report, null, 2)}\n`],
    [artifacts[1], renderHeader(maxArguments, catalogHash)],
    [artifacts[2], renderJsiHeader(recipes.length)],
    [artifacts[3], renderCpp(recipes, catalogHash)],
    [artifacts[4], renderJsiSource(catalogHash)],
    [artifacts[5], renderWeb(recipes, maxArguments, catalogHash)],
    [artifacts[6], renderTypeScript(recipes, catalogHash)],
    [artifacts[7], generateDmSdkBrowserArena(report)],
    [artifacts[8], staticFrame.staticHermes],
    [artifacts[9], renderRecipesModule(recipes, sourceHash, catalogHash)],
    [artifacts[12], staticFrame.header],
    [artifacts[13], staticFrame.source],
    [dmSdkUniversalReadyCorpusArtifacts.plan, `${JSON.stringify(readyCorpus.report, null, 2)}\n`],
    [dmSdkUniversalReadyCorpusArtifacts.productionSource, readyCorpus.generated.source],
    [dmSdkUniversalReadyCorpusArtifacts.verificationSource, readyCorpus.generated.verificationSource],
  ]);
  const endianRecipes = ["dmEndian::ToNetwork", "dmEndian::ToHost"].map((symbol) => {
    const matches = recipes.filter((recipe) => recipe.symbol === symbol && recipe.abi.parameters[0]?.nativeType === "uint32_t");
    if (matches.length !== 1) throw new Error(`Expected one uint32_t ${symbol} recipe, got ${matches.length}`);
    return matches[0];
  });
  const fixture = materializeDmSdkUsages(endianRecipes.map((recipe, index) => ({
    declarationId: recipe.declarationId,
    wrapper: index === 0 ? "deherm_test_to_network" : "deherm_test_to_host",
    acknowledgements: { generatedAdapterBypass: { reason: "generated native JSI integration fixture", evidence: "round-trip through Hermes, C ABI dispatcher, and generated thunk" } },
  })), { recipes, catalogSha256: catalogHash, providerName: "deherm_dmsdk_test_provider", installName: "deherm_dmsdk_test_provider_install" });
  outputs.set(artifacts[10], fixture.source);
  outputs.set(artifacts[11], `// ${banner}\n#pragma once\n#define DEHERM_TEST_TO_NETWORK_ID ${endianRecipes[0].numericId}\n#define DEHERM_TEST_TO_HOST_ID ${endianRecipes[1].numericId}\n#define DEHERM_TEST_DMSDK_CATALOG_SHA256 ${JSON.stringify(catalogHash)}\n`);
  for (const [relative, contents] of outputs) await writeArtifact(outRoot, relative, contents, false);
  return report;
}

export async function run(argv = process.argv.slice(2)) {
  const options = parseArguments(argv);
  if (!options.check) {
    const report = await buildUniversalDmSdkBindings({ outRoot: options.outRoot, projectionPath: options.projection, sdkIrPath: options.sdkIr });
    process.stdout.write(`Generated ${report.coverage.recipes}/${report.coverage.declarations} dmSDK universal recipes with zero omissions.\n`);
    return report;
  }
  const temporary = await mkdtemp(path.join(tmpdir(), "deherm-dmsdk-universal-check-"));
  let report;
  try {
    report = await buildUniversalDmSdkBindings({ outRoot: temporary, projectionPath: options.projection, sdkIrPath: options.sdkIr });
    for (const relative of artifacts) {
      const [expected, actual] = await Promise.all([readFile(path.join(temporary, relative)), readFile(path.join(options.outRoot, relative))]);
      if (!expected.equals(actual)) throw new Error(`${relative} is stale`);
    }
  } finally {
    await rm(temporary, { recursive: true, force: true });
  }
  process.stdout.write(`Verified ${report.coverage.recipes}/${report.coverage.declarations} dmSDK universal recipes with zero omissions.\n`);
  return report;
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? "").href) run().catch((error) => { console.error(error.stack ?? error); process.exitCode = 1; });
